SELECT COUNT(*) FROM cars_data WHERE Id IN (
  SELECT MakeId FROM car_names WHERE Make IN (
    SELECT Maker FROM car_makers WHERE Country = (
      SELECT CountryId FROM countries WHERE CountryName = 'USA'
    )
  )
)

SELECT uid FROM airlines WHERE uid IN (
  SELECT Airline FROM flights GROUP BY Airline ORDER BY COUNT(*) ASC LIMIT 1
)

SELECT * FROM airlines WHERE uid IN (
    SELECT Airline FROM flights WHERE SourceAirport IN (
        SELECT AirportCode FROM airports WHERE AirportName = '長沙'
    )
    INTERSECT
    SELECT Airline FROM flights WHERE SourceAirport IN (
        SELECT AirportCode FROM airports WHERE AirportName = '白雲'
    )
)

SELECT e.Age, e.City
FROM employee e
INNER JOIN hiring h ON e.Employee_ID = h.Employee_ID;

SELECT name FROM battle WHERE bulgarian_commander = '卡洛揚' AND name NOT IN (SELECT name FROM battle WHERE latin_commander = '鮑德溫一世')
UNION
SELECT name FROM battle WHERE latin_commander = '鮑德溫一世' AND name NOT IN (SELECT name FROM battle WHERE bulgarian_commander = '卡洛揚');
